# -*- coding: utf-8 -*-
"""Lecture 33 vignette pool A -- Oxygen Delivery: choosing and escalating a device, the indications and
the myocardial infarction caution, hazards on a patient, judging the response, nebulizer or inhaler, and
the patient who is not ventilating (slides 3-4, 8-25).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in; several carry comorbidities that decide between similar devices
(Jaxon 2026-10-29: the real CMS exam picks among similar options by the patient's comorbidity). Each
explanation says why that option fits or fails THIS patient, names the clue, and gives the replacing fact.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e6l33_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


